from decimal import Decimal, getcontext, ROUND_HALF_UP, ROUND_DOWN, InvalidOperation

getcontext().prec = 80

Q2 = Decimal("0.01")
MAX_14_2 = Decimal("1000000000000")  # NUMBER(14,2): 12 digitos enteros

DEFAULT_PARAMS = {
    "DIAS_MAX_DENUNCIA": Decimal("30"),
    "DIAS_MAX_DENUNCIA_VIDA": Decimal("365"),
    "DEDUCIBLE_MINIMO": Decimal("100"),
    "PCT_DESCUENTO_DED_VIP": Decimal("50"),
    "TOLERANCIA_MORA_VIP": Decimal("500"),
    "MAX_SINIESTROS_ANUAL": Decimal("3"),
    "PCT_PENALIZACION_SINIEST": Decimal("10"),
    "UMBRAL_RETENCION": Decimal("10000"),
    "TASA_RETENCION": Decimal("2"),
    "TOPE_AUTO_APROBACION": Decimal("50000"),
    "DIAS_ALERTA_FRAUDE": Decimal("15"),
    "PCT_ALERTA_FRAUDE": Decimal("80"),
    "FACTOR_INFLACION": Decimal("1.035"),
    "TASA_IVA": Decimal("19"),
}


def _raise_err(code):
    raise ValueError(code)


def _dec(s, default=None):
    if s is None:
        return default
    t = str(s).strip()
    if t == "" or t.upper() in ("NULL", "NONE"):
        return default
    try:
        return Decimal(t)
    except (InvalidOperation, ValueError):
        return default


def _num14_2(v):
    # Asignacion a variable NUMBER(14,2): redondeo a 2 decimales (mitad hacia arriba)
    r = v.quantize(Q2, rounding=ROUND_HALF_UP)
    if abs(r) >= MAX_14_2:
        _raise_err("ORA-06502")
    return r


def _round2(v):
    return v.quantize(Q2, rounding=ROUND_HALF_UP)


def _fmt2(v):
    return str(v.quantize(Q2, rounding=ROUND_HALF_UP))


def _days_from_civil(y, m, d):
    y2 = y - 1 if m <= 2 else y
    era = (y2 if y2 >= 0 else y2 - 399) // 400
    yoe = y2 - era * 400
    mp = m - 3 if m > 2 else m + 9
    doy = (153 * mp + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def _date_ord(s):
    t = str(s).strip()[:10]
    t = t.replace("/", "-")
    parts = t.split("-")
    if len(parts) != 3:
        _raise_err("INVALID_DATE")
    y = int(parts[0])
    m = int(parts[1])
    d = int(parts[2])
    return _days_from_civil(y, m, d)


def _bool(s):
    t = str(s if s is not None else "").strip().upper()
    return t in ("TRUE", "1", "Y", "YES", "S", "SI", "T")


def _parse_params(s):
    params = dict(DEFAULT_PARAMS)
    if s is None:
        return params
    t = str(s)
    for ch in "{}[]\"'":
        t = t.replace(ch, "")
    t = t.replace(";", ",").replace("\n", ",").replace("\r", ",")
    for item in t.split(","):
        item = item.strip()
        if item == "":
            continue
        sep_idx = -1
        for i in range(len(item)):
            if item[i] == ":" or item[i] == "=":
                sep_idx = i
                break
        if sep_idx < 0:
            continue
        k = item[:sep_idx].strip().upper()
        v = _dec(item[sep_idx + 1:].strip(), None)
        if k != "" and v is not None:
            params[k] = v
    return params


def _p(params, name):
    if name not in params or params[name] is None:
        _raise_err("ORA-20010")
    return params[name]


def _result(status, reason, base, ded, cub, ret, neto, obs, err):
    return {
        "status": status,
        "reason_code": reason,
        "base_amount": _fmt2(base),
        "deductible_amount": _fmt2(ded),
        "covered_amount": _fmt2(cub),
        "withholding_amount": _fmt2(ret),
        "net_amount": _fmt2(neto),
        "observations": obs if obs is not None else "",
        "error_code": err,
    }


def _add_obs(obs, mark):
    if obs is None or obs == "":
        return mark
    return obs + ";" + mark


def _reject(reason, obs=None):
    z = Decimal("0")
    return _result("RECHAZADA", reason, z, z, z, z, z, obs, "")


def _liquidar(inp):
    params = _parse_params(inp.get("business_parameters"))

    claim_amount = _dec(inp.get("claim_amount"), Decimal("0"))
    occ = _date_ord(inp.get("occurrence_date"))
    rep = _date_ord(inp.get("report_date"))
    pol_status = str(inp.get("policy_status") or "").strip()
    branch = str(inp.get("policy_branch") or "").strip()
    pol_start = _date_ord(inp.get("policy_start_date"))
    pol_end = _date_ord(inp.get("policy_end_date"))
    sum_insured = _dec(inp.get("sum_insured"), Decimal("0"))
    ded_type = str(inp.get("deductible_type") or "").strip()
    ded_value = _dec(inp.get("deductible_value"), Decimal("0"))
    pending = _dec(inp.get("pending_premium"), Decimal("0"))
    category = str(inp.get("customer_category") or "").strip()
    cov_found = _bool(inp.get("coverage_found"))
    cov_limit = _dec(inp.get("coverage_limit"), Decimal("0"))
    cov_pct = _dec(inp.get("coverage_percentage"), Decimal("0"))
    waiting = _dec(inp.get("waiting_days"), Decimal("0"))
    prior_cnt = _dec(inp.get("prior_liquidated_claims_365d"), Decimal("0"))
    total_indem = _dec(inp.get("total_indemnified"), Decimal("0"))

    obs = None

    # Carga de FACTOR_INFLACION (no usado, pero puede lanzar ORA-20010)
    _p(params, "FACTOR_INFLACION")

    # 1.a Estado de la poliza
    if pol_status != "VIGENTE":
        return _reject("POLIZA_NO_VIGENTE")

    # 1.b Vigencia
    if occ < pol_start or occ > pol_end:
        return _reject("FUERA_DE_VIGENCIA")

    # 1.c Plazo de denuncia
    dias_denuncia = Decimal(rep - occ)
    if branch == "VIDA":
        dias_max = _p(params, "DIAS_MAX_DENUNCIA_VIDA")
    else:
        dias_max = _p(params, "DIAS_MAX_DENUNCIA")
    if dias_denuncia > dias_max:
        return _reject("DENUNCIA_EXTEMPORANEA")

    # 1.d Cobertura contratada
    if not cov_found:
        return _reject("COBERTURA_NO_CONTRATADA")

    # 1.e Carencia
    dias_desde_inicio = Decimal(occ - pol_start)
    if dias_desde_inicio < waiting:
        return _reject("EN_PERIODO_CARENCIA")

    # 1.f Morosidad
    if pending > 0:
        tol = _p(params, "TOLERANCIA_MORA_VIP")
        if category == "VIP" and pending <= tol:
            obs = _add_obs(obs, "TOLERANCIA_MORA_VIP")
        else:
            return _reject("PRIMA_EN_MORA", obs)

    # 2.a Monto base
    if claim_amount > cov_limit:
        monto_base = _num14_2(cov_limit)
        obs = _add_obs(obs, "LIMITE_COBERTURA")
    else:
        monto_base = _num14_2(claim_amount)

    # 2.b Deducible (fn_calcular_deducible, v_deducible NUMBER(14,2))
    if ded_type == "FIJO":
        deducible = _num14_2(ded_value)
    else:
        ded_min = _p(params, "DEDUCIBLE_MINIMO")
        deducible = _num14_2(_round2(monto_base * ded_value / Decimal(100)))
        if deducible < ded_min:
            deducible = _num14_2(ded_min)
            obs = _add_obs(obs, "DEDUCIBLE_MINIMO")
    if category == "VIP" and deducible > 0:
        pct_vip = _p(params, "PCT_DESCUENTO_DED_VIP")
        deducible = _num14_2(_round2(deducible * (Decimal(100) - pct_vip) / Decimal(100)))
        obs = _add_obs(obs, "DESCUENTO_VIP")
    deducible = _num14_2(deducible)

    # 2.c Monto cubierto
    cubierto = _num14_2(_round2((monto_base - deducible) * cov_pct / Decimal(100)))
    if cubierto <= 0:
        return _reject("BAJO_DEDUCIBLE", obs)

    # 2.d Siniestralidad
    if prior_cnt >= _p(params, "MAX_SINIESTROS_ANUAL"):
        pen = _p(params, "PCT_PENALIZACION_SINIEST")
        cubierto = _num14_2(_round2(cubierto * (Decimal(100) - pen) / Decimal(100)))
        obs = _add_obs(obs, "PENALIZACION_SINIESTRALIDAD")

    # 2.e Suma asegurada remanente
    remanente = sum_insured - total_indem
    if remanente <= 0:
        return _reject("SUMA_ASEGURADA_AGOTADA", obs)
    if cubierto > remanente:
        cubierto = _num14_2(remanente)
        obs = _add_obs(obs, "TOPE_SUMA_ASEGURADA")

    # 2.f Retencion
    if branch != "VIDA" and cubierto > _p(params, "UMBRAL_RETENCION"):
        tasa = _p(params, "TASA_RETENCION")
        retencion = _num14_2(_round2(cubierto * tasa / Decimal(100)))
        obs = _add_obs(obs, "RETENCION_APLICADA")
    else:
        retencion = Decimal("0.00")
    neto = _num14_2(cubierto - retencion)

    # 3. Estado final
    umbral_fraude = _round2(cov_limit * _p(params, "PCT_ALERTA_FRAUDE") / Decimal(100))
    if dias_desde_inicio <= _p(params, "DIAS_ALERTA_FRAUDE") and claim_amount >= umbral_fraude:
        status = "PENDIENTE_APROBACION"
        reason = "SOSPECHA_FRAUDE"
    elif neto > _p(params, "TOPE_AUTO_APROBACION"):
        status = "PENDIENTE_APROBACION"
        reason = "SUPERA_TOPE_AUTOMATICO"
    else:
        status = "APROBADA"
        reason = "LIQUIDACION_AUTOMATICA"

    return _result(status, reason, monto_base, deducible, cubierto, retencion, neto, obs, "")


def run(inp: dict) -> dict:
    try:
        return _liquidar(inp)
    except ValueError as ex:
        code = str(ex.args[0]) if ex.args else "ERROR"
        z = Decimal("0")
        return _result("", "", z, z, z, z, z, "", code)
